// Aritmética mía sobre el tope de la tabla de Google (bucket «raro»: 10 minutos de trabajo en 24 horas).
const topeSegundos = 10 * 60;
const duracion = 20;                      // cada sincronización, en segundos
const caben = Math.floor(topeSegundos / duracion);
const pedidas = (24 * 60) / 15;           // piso de WorkManager periódico: 15 minutos
console.log('caben en el cupo:', caben);
console.log('pide la app por día:', pedidas);
console.log('cada cuántos minutos, en promedio, si se reparten parejo:', (24 * 60 / caben).toFixed(0));

OneTimeWorkRequest.Builder builder =
    new OneTimeWorkRequest.Builder(RNWidgetBackgroundTaskWorker.class)
        .setInputData(data);

// Reduce background scheduling delays on Android 12+.
// Falls back to regular work if expedited quota is exhausted.
if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
    builder.setExpedited(OutOfQuotaPolicy.RUN_AS_NON_EXPEDITED_WORK_REQUEST);
}
WorkManager.getInstance(context).enqueue(builder.build());
